questions.sample:
provider "google" {
  project = var.project_id
  region  = "us-central1"
}

resource "google_storage_bucket" "pedidos_raw" {
  name                        = var.nome_bucket
  location                    = "US-CENTRAL1"
  uniform_bucket_level_access = true
}

variable "ambiente" {
  type        = string
  description = "Ambiente de execução"

  validation {
    condition     = contains(["dev", "staging", "prod"], var.ambiente)
    error_message = "ambiente precisa ser dev, staging ou prod."
  }
}

output "bucket_url" {
  value = google_storage_bucket.pedidos_raw.url
}
